#!/usr/bin/env bash
set -euo pipefail

CONFIG_DIR="${XDG_CONFIG_HOME:-$HOME/.config}/opencode"
AGENTS_DIR="$CONFIG_DIR/agents"

echo "🎓 OpenStudy — Configurando agentes académicos..."
mkdir -p "$AGENTS_DIR"

install_if_missing() {
  local file="$1"
  local content="$2"
  if [ ! -f "$file" ]; then
    printf '%s' "$content" | base64 -d > "$file"
    echo "  ✓ $(basename "$file")"
  else
    echo "  · $(basename "$file") (ya existe, no se modifica)"
  fi
}

write_config_if_missing() {
  local file="$1"
  if [ ! -f "$file" ]; then
    cat > "$file" <<'JSON'
{
  "$schema": "https://opencode.ai/config.json",
  "plugin": ["opencode-anthropic-login-via-cli@latest"],
  "agent": {
    "neux-profesor": {
      "model": "anthropic/claude-sonnet-4-20250514",
      "temperature": 0.4,
      "color": "#7C3AED",
      "permission": {
        "edit": "ask",
        "bash": {
          "*": "deny",
          "open *": "allow",
          "ls *": "allow",
          "find *": "allow",
          "cat *": "allow",
          "grep *": "allow"
        }
      }
    },
    "neux-tutor": {
      "model": "anthropic/claude-sonnet-4-20250514",
      "temperature": 0.2,
      "color": "#0891B2",
      "permission": {
        "edit": "deny",
        "bash": {
          "*": "deny",
          "ls *": "allow",
          "find *": "allow",
          "cat *": "allow",
          "grep *": "allow"
        },
        "webfetch": "allow"
      }
    },
    "neux-investigador": {
      "model": "anthropic/claude-sonnet-4-20250514",
      "temperature": 0.3,
      "permission": {
        "edit": "deny",
        "bash": {
          "*": "deny",
          "curl *": "allow"
        },
        "webfetch": "allow"
      }
    },
    "neux-explorador": {
      "model": "anthropic/claude-sonnet-4-20250514",
      "temperature": 0.3,
      "color": "#10B981",
      "permission": {
        "edit": "deny",
        "bash": {
          "*": "deny",
          "ls *": "allow",
          "find *": "allow",
          "cat *": "allow",
          "grep *": "allow"
        }
      }
    }
  },
  "mcp": {
    "filesystem": {
      "type": "local",
      "command": ["mcp-server-filesystem", "."]
    },
    "engram": {
      "type": "local",
      "command": ["engram", "mcp"]
    },
    "notion": {
      "type": "local",
      "command": ["notion-mcp-server"],
      "environment": {
        "NOTION_TOKEN": "{env:NOTION_TOKEN}"
      }
    },
    "notebooklm": {
      "type": "local",
      "command": ["notebooklm-mcp"],
      "environment": {
        "NOTEBOOKLM_PROFILE": "minimal"
      }
    }
  }
}
JSON
    echo "  ✓ $(basename "$file")"
  else
    echo "  · $(basename "$file") (ya existe, no se modifica)"
  fi
}

install_if_missing "$AGENTS_DIR/neux-profesor.md" ""
install_if_missing "$AGENTS_DIR/neux-tutor.md" ""
install_if_missing "$AGENTS_DIR/neux-investigador.md" ""
install_if_missing "$AGENTS_DIR/neux-explorador.md" ""
install_if_missing "$CONFIG_DIR/AGENTS.md" ""
write_config_if_missing "$CONFIG_DIR/opencode.json"

echo ""
echo "✅ OpenStudy listo. Ejecuta: openstudy"
echo ""
echo "Agentes instalados:"
echo "  • Neux Profesor  — tutorías, resúmenes, flashcards, exámenes"
echo "  • Neux Tutor     — retroalimentación y análisis (solo lectura)"
echo "  • Neux Investigador — investigación académica profunda"
echo "  • Neux Explorador   — navegación de archivos de estudio"
echo ""
echo "Necesitas una API key de un proveedor de IA."
echo "Configúrala con: openstudy providers login"
